mapper.select:
SELECT de.*, dt.order_id, rp.real_name AS rider_name, b.business_name, u.username AS customer_name FROM delivery_exception de JOIN delivery_task dt ON dt.id = de.task_id JOIN orders o ON o.id = dt.order_id JOIN business b ON b.id = o.business_id JOIN users u ON u.id = o.customer_id LEFT JOIN rider_profile rp ON rp.user_id = de.rider_user_id
de.status = #{status}
ORDER BY de.create_time DESC
